<?php
/**
 * SugarCommerce Geo
 *
 * How each country writes an address: the order of the parts, what it calls
 * its region, its postcode and its town, which of them must be filled in, and
 * what its postcodes look like.
 *
 * The table is data/address-formats.php, generated by
 * bin/generate-address-formats.php from the address metadata behind
 * Google's libaddressinput and used under CC-BY 4.0; its own comment carries
 * the attribution. This class, the code that reads it, is GPL-3.0-or-later,
 * like the rest of the library.
 *
 * @package     SugarCommerce\Geo
 * @copyright   Copyright (c) 2026, ArrayPress Limited
 * @license     GPL-3.0-or-later
 * @author      David Sherlock
 */

declare( strict_types=1 );

namespace SugarCommerce\Geo;

use SugarCommerce\Geo\Utils\Data;

/**
 * AddressFormats class
 *
 * The table and nothing else. Addresses is what reads it.
 *
 * @since 1.0.0
 */
class AddressFormats {

	/**
	 * The format of a country that is not in the table at all.
	 *
	 * Every part, in the order most of the world reads without surprise.
	 * Not the same thing as a country that is in the table with a short
	 * format: that one is known to have no postcode, and this one is only
	 * not known.
	 *
	 * The parts are %N name, %O organisation, %A street lines, %C town,
	 * %S region, %Z postcode; %n starts a new line; anything else is
	 * printed as it is.
	 */
	public const string UNKNOWN = '%N%n%O%n%A%n%C%n%S%n%Z';

	/**
	 * The parts that must be filled in where a country does not say.
	 *
	 * The data's own default, used for a country with no `require` of its
	 * own and for one that is not in the table: A street, C town. The
	 * generator stops if the data's default ever stops being this.
	 */
	public const string REQUIRE = 'AC';

	/**
	 * The parts written in capitals where a country does not say.
	 */
	public const string UPPER = 'C';

	/**
	 * Formats, by country.
	 *
	 * `format` is the address as the country writes it; `latin`, where
	 * there is one, the same address in Latin letters. `region`, `postcode`
	 * and `city` say what the part is called there; `require` and `upper`
	 * the parts a form must have filled in and the parts written in
	 * capitals, where they are not REQUIRE and UPPER; `zip` what a postcode
	 * there looks like, and `zip_example` one that fits it. The data file's
	 * comment says more. A country that is not here is written as UNKNOWN.
	 *
	 * @return array<string, array<string, string>> By upper-case country code.
	 * @since 1.0.0
	 */
	public static function all(): array {
		return Data::get( 'address-formats' );
	}

	/**
	 * One country's format.
	 *
	 * @param string $country Country code (case-insensitive).
	 *
	 * @return array<string, string>|null The row, as all() has it; null for
	 *                                    a country that is not in the table.
	 * @since 1.0.0
	 */
	public static function get( string $country ): ?array {
		return self::all()[ strtoupper( trim( $country ) ) ] ?? null;
	}
}
